// CPU cache characterization: pack each unchanged 512x64 way into one byte-enabled synchronous array.
// R23: ready-qualified speculative I payload reads; accepted handshakes/state unchanged.
// R16: cache response data is an unqualified proposal; valid/errors and accepted-cycle payloads are unchanged.
// FPGA RAM port adaptation of the original RV32 cache.
// Generated by lower_cache_ports.py; original source SHA-256: 275eceb22039d4f0b742c922b29d101c2d13b89cf312311fb21e818901523666
// Original RV32 memory system. Designed from the neutral bus contract.
// No reference RTL, generated code, or third-party CPU implementation used.
// All cache-array reads are clocked. Instruction banks are 32 bits; data
// segments are 64 bits. Cache data/tag arrays are not reset;
// deterministic valid/dirty bits prevent uninitialized contents being observed.
module rv32_memory_system #(
    parameter I_INDEX_BITS = 8,
    parameter D_INDEX_BITS = 6,
    parameter D_WAYS = 2,
    parameter D1_COMPAT = 0,
    parameter [31:0] D1_CACHE_BASE=32'h84000000,
    parameter [32:0] D1_CACHE_BYTES=33'h004000000,
    // Opt-in parallel next-line tag lookup. Data-bank ports remain synchronous.
    parameter ENABLE_FAST_ICROSS = 0,
    // Optional board-map knowledge, disabled for reusable/DDR systems. Bounds
    // are inclusive and line aligned. No address addition can wrap at 4 GiB.
    parameter ENABLE_DATA_RAM_GUARD = 0,
    parameter [31:0] DATA_RAM_BASE = 32'h00000000,
    parameter [31:0] DATA_RAM_LIMIT = 32'hffffffff
)(
    input clk, reset,
    input imem_request_valid, output imem_request_ready,
    input [31:0] imem_request_address,
    output reg imem_response_valid, input imem_response_ready,
    output reg [63:0] imem_response_data,
    output reg [1:0] imem_response_error,
    input dmem_request_valid, output dmem_request_ready,
    input [31:0] dmem_request_address,
    input dmem_request_write,
    input [31:0] dmem_request_wdata,
    input [3:0] dmem_request_wstrb,
    input [1:0] dmem_request_size,
    output reg dmem_response_valid, input dmem_response_ready,
    output reg [31:0] dmem_response_rdata,
    output reg dmem_response_error,
    input fence_i, fence_d,
    output maintenance_busy,
    output event_icache_refill, event_dcache_refill, event_dcache_writeback,
    output event_icache_hit,event_icache_miss,event_dcache_hit,event_dcache_miss,
    output instr_req_o, input instr_gnt_i,
    output [31:0] instr_addr_o, output instr_io_o,
    input instr_rvalid_i, output instr_rready_o,
    input [63:0] instr_rdata_i, input instr_err_i,
    output data_rd_req_o, input data_rd_gnt_i,
    output data_rd_id_o, output [31:0] data_rd_addr_o,
    input data_rd_rvalid_i, output data_rd_rready_o,
    input data_rd_rid_i, input [63:0] data_rd_rdata_i,
    input data_rd_err_i,
    output data_wr_req_o, input data_wr_gnt_i,
    output data_wr_last_o, output [31:0] data_wr_addr_o,
    output [63:0] data_wr_data_o, output data_wr_id_o,
    input data_wr_bvalid_i, input data_wr_berr_i, input data_wr_bid_i,
    output periph_req_o, input periph_gnt_i,
    output periph_we_o, output [31:0] periph_addr_o,
    output [31:0] periph_wdata_o, output [3:0] periph_be_o,
    output [1:0] periph_size_o,
    input periph_rvalid_i, input periph_err_i,
    input [31:0] periph_rdata_i
);
    localparam I_LINES = (1 << I_INDEX_BITS);
    localparam D_LINES = (1 << D_INDEX_BITS);
    localparam I_TAG_BITS = 26-I_INDEX_BITS;
    localparam D_TAG_BITS = 26-D_INDEX_BITS;
    localparam [2:0] I_IDLE=0, I_LOOKUP=1, I_COMMAND=2,
                     I_FILL=3, I_ERROR=4;
    localparam [3:0] D_IDLE=0, D_LOOKUP=1, D_READ_COMMAND=2,
                     D_FILL=3, D_WRITE_BEATS=4, D_WRITE_ACK=5,
                     D_IO_COMMAND=6, D_IO_WAIT=7, D_RESPONSE=8,
                     D_SWEEP_READ=9, D_SWEEP_CHECK=10, D_WRITE_READ=11;

    (* syn_ramstyle="block_ram" *)reg [31:0] instruction_even [0:I_LINES*8-1];
    (* syn_ramstyle="block_ram" *)reg [31:0] instruction_odd [0:I_LINES*8-1];
    reg [I_TAG_BITS-1:0] instruction_tags [0:I_LINES-1];
    reg instruction_valid [0:I_LINES-1];
    (* syn_ramstyle="block_ram" *) reg [63:0] data_segments [0:D_LINES*8-1];
    reg [D_TAG_BITS-1:0] data_tags [0:D_LINES-1];
    reg data_valid [0:D_LINES-1];
    reg data_dirty [0:D_LINES-1];
    (* syn_ramstyle="block_ram" *) reg [63:0] data_segments_second [0:D_LINES*8-1];
    reg [D_TAG_BITS-1:0] data_tags_second [0:D_LINES-1];
    reg data_valid_second [0:D_LINES-1];
    reg data_dirty_second [0:D_LINES-1];
    reg data_lru [0:D_LINES-1];

    reg [2:0] i_state;
    reg [31:0] i_address;
    wire [31:0] i_even_word, i_odd_word;
    wire [31:0] i_word0=i_address[2] ? i_odd_word : i_even_word;
    wire [31:0] i_word1=i_address[2] ? i_even_word : i_odd_word;
    reg [I_TAG_BITS-1:0] i_tag;
    reg i_valid;
    reg [I_TAG_BITS-1:0] i_next_tag;
    reg i_next_valid;
    reg i_crossing;
    reg [31:0] i_first_word;
    reg i_first_error;
    reg [2:0] i_beat;
    reg i_fill_error;
    // R48: all original error payload upper words are zero. Only validity
    // receives late ownership/error decisions. Raw lower-word proposals use
    // registered cache state/address and are private outside I_ERROR.
    reg [63:0] i_error_data_snapshot;
    reg [31:0] i_error_word;
    reg i_error_word_valid;
    wire [63:0] i_error_data={32'b0,i_error_word_valid?i_error_word:32'b0};
`ifdef VERILATOR
    always @(posedge clk)if(!reset&&i_state==I_ERROR&&i_error_data!=i_error_data_snapshot)
        $fatal(1,"R48 owned error payload differs from original cache register");
`endif
    reg [1:0] i_error_bits;
    wire [I_INDEX_BITS-1:0] i_index = i_address[6+I_INDEX_BITS-1:6];
    wire i_hit = i_valid && i_tag == i_address[31:6+I_INDEX_BITS];
    wire [31:0] i_next_address = i_address + 32'd4;
    wire [I_INDEX_BITS-1:0] i_next_index = i_next_address[6+I_INDEX_BITS-1:6];
    // The normal even-bank request read already addresses word1 across a line.
    // Its separate, clocked tag/valid snapshot grants that payload ownership
    // only when both lines hit and the second word remains executable. Nothing
    // changes on a miss or fault; those retain the original precise sequence.
    wire i_fast_cross_hit = ENABLE_FAST_ICROSS && !i_crossing &&
        i_address[5:2]==4'd15 && executable(i_next_address) &&
        i_next_valid && i_next_tag==i_next_address[31:6+I_INDEX_BITS];
    wire [31:0] new_i_next_address = imem_request_address + 32'd4;
    wire [I_INDEX_BITS-1:0] new_i_next_index = new_i_next_address[6+I_INDEX_BITS-1:6];

    reg [3:0] d_state;
    reg [31:0] d_address;
    reg d_write;
    reg [31:0] d_wdata;
    reg [3:0] d_wstrb;
    reg [1:0] d_size;
    wire [63:0] d_segment, d_second_segment;
    reg [D_TAG_BITS-1:0] d_tag;
    reg d_valid, d_dirty;
    reg [D_TAG_BITS-1:0] d_second_tag;
    reg d_second_valid, d_second_dirty, d_lru;
    reg request_way, writeback_way, sweep_way;
    reg [2:0] d_beat;
    reg d_fill_error;
    reg [31:0] d_result;
    reg d_result_error;
    reg [31:0] writeback_address;
    reg [D_INDEX_BITS-1:0] writeback_index;
    reg writeback_is_sweep;
    reg [D_INDEX_BITS-1:0] sweep_index;
    reg fence_pending, invalidate_data;
    wire [D_INDEX_BITS-1:0] d_index = d_address[6+D_INDEX_BITS-1:6];
    wire d_match_first = d_valid && d_tag == d_address[31:6+D_INDEX_BITS];
    wire d_match_second = D_WAYS>1 && d_second_valid &&
                          d_second_tag == d_address[31:6+D_INDEX_BITS];
    wire d_hit = d_match_first || d_match_second;
    wire selected_way = d_match_first ? 1'b0 : d_match_second ? 1'b1 :
                        !d_valid ? 1'b0 : (D_WAYS>1 && !d_second_valid) ? 1'b1 :
                        (D_WAYS>1 && d_lru);
    wire selected_valid=selected_way ? d_second_valid : d_valid;
    wire selected_dirty=selected_way ? d_second_dirty : d_dirty;
    wire [D_TAG_BITS-1:0] selected_tag=selected_way ? d_second_tag : d_tag;
    wire [63:0] selected_segment=selected_way ? d_second_segment : d_segment;
    wire sweep_is_last=(sweep_index==D_LINES-1) && (D_WAYS==1 || sweep_way);
    wire i_complete = imem_response_valid && imem_response_ready;
    wire d_complete = dmem_response_valid && dmem_response_ready;
    wire new_i = imem_request_valid && imem_request_ready;
    // A speculative RAM/tag payload read grants no request/state ownership.
    // Ready is true only at idle or an actual response transfer, so a held
    // valid response cannot be overwritten. Remove frontend late correction
    // /request_valid from the synchronous RAM read-address selection.
    // Payload reads are safe at every idle/response-transfer edge, including
    // non-executable or unaligned private addresses. Actual new_i ownership
    // still validates the full address and returns the original precise error.
    // Never overwrite a held response: ready remains false under backpressure.
    // Maintenance still blocks actual request readiness/ownership. Reading
    // private payload while idle (or consuming a real held response) cannot
    // acquire state, and avoids a late fence/recovery cone on RAM addresses.
    wire i_speculative_read=!reset&&(i_state==I_IDLE||i_complete);
    wire new_d = dmem_request_valid && dmem_request_ready;
    wire maintenance_request = fence_pending || fence_i || fence_d;
    // Free payload capture does not acquire a request, change state, or
    // start an IO transaction. Maintenance and held responses retain fields.
    wire d_payload_free=dmem_request_ready;
`ifdef VERILATOR
    reg prior_d_owned;
    reg [70:0] prior_d_payload;
    always @(posedge clk)begin
        if(reset)begin prior_d_owned<=0;prior_d_payload<=0;end
        else begin
            if(new_d&&!d_payload_free)$fatal(1,"R42 accepted data request without free private payload slot");
            if(prior_d_owned&&{d_address,d_write,d_wdata,d_wstrb,d_size}!=prior_d_payload)
                $fatal(1,"R42 owned cache request payload differs from original accepted request");
            if(new_d)begin prior_d_owned<=1;prior_d_payload<=
                {dmem_request_address,dmem_request_write,dmem_request_wdata,dmem_request_wstrb,dmem_request_size};end
            else if(d_complete)prior_d_owned<=0;
        end
    end
`endif
    wire [D_INDEX_BITS-1:0] next_d_index = dmem_request_address[6+D_INDEX_BITS-1:6];
    wire [D_INDEX_BITS+2:0] d_segment_index=d_address[6+D_INDEX_BITS-1:3];
    wire [D_INDEX_BITS+2:0] next_d_segment=dmem_request_address[6+D_INDEX_BITS-1:3];
    wire [I_INDEX_BITS+2:0] new_i_pair=imem_request_address[6+I_INDEX_BITS-1:3];
    wire [I_INDEX_BITS+2:0] new_i_even_pair=new_i_pair+{{(I_INDEX_BITS+2){1'b0}},imem_request_address[2]};
    wire [I_INDEX_BITS+2:0] cross_i_pair=i_next_address[6+I_INDEX_BITS-1:3];
    wire [2:0] next_write_beat=d_beat+3'd1;
    wire [7:0] store_byte_enable=d_address[2] ? {d_wstrb,4'b0} : {4'b0,d_wstrb};
    wire [63:0] store_replicated={d_wdata,d_wdata};
    integer n;

    function executable;
        input [31:0] address;
        begin executable = (address[31:28]==4'h1 || address[31:28]==4'h8); end
    endfunction
    function peripheral;
        input [31:0] address;
        begin
            // D1: only its private 64 MiB aperture is write-back cacheable.
            // TCM, shared DMA/video/model DDR, all MMIO and invalid ranges
            // take the owned uncached adapter. No extra D1 D-cache exists.
            peripheral = D1_COMPAT ? !({1'b0,address}>={1'b0,D1_CACHE_BASE} &&
                {1'b0,address}<{1'b0,D1_CACHE_BASE}+D1_CACHE_BYTES) :
                ((address >= 32'h30000000 && address < 32'h80000000) ||
                 (address >= 32'h80000000 && address < 32'h84000000));
        end
    endfunction
    function data_ram_mapped;
        input [31:0] address;
        begin
            data_ram_mapped = !ENABLE_DATA_RAM_GUARD ||
                (address >= DATA_RAM_BASE && address <= DATA_RAM_LIMIT);
        end
    endfunction
`ifdef VERILATOR
    initial if (ENABLE_DATA_RAM_GUARD &&
        (DATA_RAM_BASE > DATA_RAM_LIMIT || DATA_RAM_BASE[5:0] != 0 ||
         DATA_RAM_LIMIT[5:0] != 6'h3f))
        $fatal(1,"Data RAM guard requires a nonwrapping, whole-cache-line range");
`endif
    function [63:0] merge_store;
        input [63:0] segment;
        input [63:0] value;
        input [7:0] enables;
        integer lane;
        begin
            merge_store=segment;
            for(lane=0;lane<8;lane=lane+1)
                if(enables[lane])merge_store[lane*8 +: 8]=value[lane*8 +: 8];
        end
    endfunction
    wire [63:0] updated_data_segment=merge_store(selected_segment,store_replicated,store_byte_enable);

    assign maintenance_busy=maintenance_request;
    // Request-level hits and misses are disjoint. A successful response after
    // refill must not also count as a hit; a crossing fetch can miss two lines.
    reg d1_i_missed,d1_d_missed;
    always @(posedge clk)begin
      if(reset)begin d1_i_missed<=0;d1_d_missed<=0;end
      else begin
        if(i_state==I_LOOKUP && !i_hit)d1_i_missed<=1;
        if(d_state==D_LOOKUP && !d_hit)d1_d_missed<=1;
        if(new_i)d1_i_missed<=0;
        if(new_d)d1_d_missed<=0;
      end
    end
    assign event_icache_hit=!reset && i_state==I_LOOKUP && i_complete && !d1_i_missed;
    assign event_icache_miss=!reset && i_state==I_LOOKUP && !i_hit && !d1_i_missed;
    assign event_dcache_hit=!reset && d_state==D_LOOKUP && d_hit && d_complete && !d1_d_missed;
    assign event_dcache_miss=!reset && d_state==D_LOOKUP && !d_hit && !d1_d_missed;
    assign event_icache_refill=!reset && i_state==I_FILL && i_beat==3'd7 &&
        instr_rvalid_i && !i_fill_error && !instr_err_i;
    assign event_dcache_refill=!reset && d_state==D_FILL && d_beat==3'd7 &&
        data_rd_rvalid_i && !d_fill_error && !data_rd_err_i && data_rd_rid_i==1'b0;
    assign event_dcache_writeback=!reset && data_wr_bvalid_i && !data_wr_berr_i &&
        data_wr_bid_i==1'b0 && (d_state==D_WRITE_ACK ||
        (d_state==D_WRITE_BEATS && d_beat==3'd7 && data_wr_gnt_i));
    assign imem_request_ready=!reset && !maintenance_request &&
                             (i_state==I_IDLE || i_complete);
    assign dmem_request_ready=!reset && !maintenance_request &&
                             (d_state==D_IDLE || d_complete);
    assign instr_req_o=!reset && i_state==I_COMMAND;
    assign instr_addr_o={i_address[31:6],6'b0};
    assign instr_io_o=peripheral(i_address);
    assign instr_rready_o=!reset && (i_state==I_FILL || i_state==I_COMMAND);
    assign data_rd_req_o=!reset && d_state==D_READ_COMMAND;
    assign data_rd_id_o=1'b0;
    assign data_rd_addr_o={d_address[31:6],6'b0};
    assign data_rd_rready_o=!reset && (d_state==D_FILL || d_state==D_READ_COMMAND);
    assign data_wr_req_o=!reset && d_state==D_WRITE_BEATS;
    assign data_wr_last_o=d_beat==3'd7;
    assign data_wr_addr_o=writeback_address;
    assign data_wr_data_o=writeback_way ? d_second_segment : d_segment;
    assign data_wr_id_o=1'b0;
    assign periph_req_o=!reset && d_state==D_IO_COMMAND;
    assign periph_we_o=d_write;
    assign periph_addr_o=d_address;
    assign periph_wdata_o=d_wdata;
    assign periph_be_o=d_write ? d_wstrb :
                       (d_size==0 ? (4'b0001 << d_address[1:0]) :
                        d_size==1 ? (4'b0011 << d_address[1:0]) : 4'b1111);
    assign periph_size_o=d_size;

    always @* begin
        imem_response_valid=1'b0;
        // Data proposals are available in parallel with tag comparison.
        // Only response_valid grants a transaction; invalid-cycle data is
        // deliberately unspecified, avoiding hit -> data -> predict feedback.
        imem_response_data=i_crossing?{i_word0,i_first_word}:{i_word1,i_word0};
        imem_response_error=2'b0;
        if (!reset && i_state==I_LOOKUP && i_hit &&
            (i_crossing || i_address[5:2]!=4'd15 || i_fast_cross_hit)) begin
            imem_response_valid=1'b1;
            if(i_crossing)imem_response_error={1'b0,i_first_error};
        end
        if (!reset && i_state==I_ERROR) begin
            imem_response_valid=1'b1;
            imem_response_data=i_error_data;
            imem_response_error=i_error_bits;
        end
        dmem_response_valid=1'b0;
        dmem_response_rdata=(d_address[2]?selected_segment[63:32]:selected_segment[31:0]);
        dmem_response_error=1'b0;
        if (!reset && d_state==D_LOOKUP && d_hit) begin
            dmem_response_valid=1'b1;
        end
        if (!reset && d_state==D_RESPONSE) begin
            dmem_response_valid=1'b1;
            dmem_response_rdata=d_result;
            dmem_response_error=d_result_error;
        end
    end


    reg [31:0] i_even_ram_q, i_even_bypass;
    reg i_even_ram_select;
    assign i_even_word=i_even_ram_select ? i_even_ram_q : i_even_bypass;
    reg [31:0] i_odd_ram_q, i_odd_bypass;
    reg i_odd_ram_select;
    assign i_odd_word=i_odd_ram_select ? i_odd_ram_q : i_odd_bypass;
    reg [63:0] d_first_ram_q, d_first_bypass;
    reg d_first_ram_select;
    assign d_segment=d_first_ram_select ? d_first_ram_q : d_first_bypass;
    reg [63:0] d_second_ram_q, d_second_bypass;
    reg d_second_ram_select;
    assign d_second_segment=d_second_ram_select ? d_second_ram_q : d_second_bypass;

    wire i_ram_cross_lookup=(i_state==I_LOOKUP && i_hit && !i_crossing && !i_fast_cross_hit &&
        i_address[5:2]==4'd15 && executable(i_next_address));
    wire i_ram_cross_error=(i_state==I_FILL && instr_rvalid_i && i_beat==3'd7 &&
        (i_fill_error || instr_err_i) && !i_crossing && i_address[5:2]==4'd15 && executable(i_next_address));
    wire i_ram_read=!reset && (i_speculative_read || i_ram_cross_lookup || i_ram_cross_error);
    // Private synchronous read payload is safe at idle or response transfer.
    // Keep actual new_d state/side-effect ownership independently qualified.
    wire d_speculative_read=!reset&&(d_state==D_IDLE||d_complete);
    wire d_ram_new_read=d_speculative_read;
    wire d_ram_writeback_read=(d_state==D_WRITE_READ) ||
        (d_state==D_WRITE_BEATS && data_wr_gnt_i && d_beat!=3'd7);
    wire d_first_ram_read=!reset && (d_ram_new_read || (d_ram_writeback_read && !writeback_way));
    wire d_second_ram_read=!reset && ((d_ram_new_read && D_WAYS>1) || (d_ram_writeback_read && writeback_way));
    always @(posedge clk) begin
        if(i_ram_read) begin
            i_even_ram_q<=instruction_even[i_even_ram_read_index];
            i_odd_ram_q<=instruction_odd[i_odd_ram_read_index];
        end
    end

    // Prepare error payload independently of current hit/fault qualification.
    // I_ERROR never overwrites its held payload; only the matching original
    // transition below can make these private bits externally meaningful.
    always @(posedge clk)if(!reset)begin
        if(i_state==I_LOOKUP&&!i_crossing&&i_address[5:2]==4'd15)
            i_error_word<=i_word0;
        else if(i_state==I_FILL&&instr_rvalid_i&&i_beat==3'd7)
            i_error_word<=i_first_word;
    end

    // FPGA RAM port lowering: unchanged architectural cycle boundary.
    wire [I_INDEX_BITS+2:0] i_even_ram_read_index=i_speculative_read ? new_i_even_pair : cross_i_pair;
    wire [I_INDEX_BITS+2:0] i_odd_ram_read_index=i_speculative_read ? new_i_pair : cross_i_pair;
    wire [I_INDEX_BITS+2:0] i_ram_write_index={i_index,(i_state==I_COMMAND ? 3'b0 : i_beat)};
    wire i_ram_write=!reset && instr_rvalid_i &&
        ((i_state==I_COMMAND && instr_gnt_i) || i_state==I_FILL);
    wire [D_INDEX_BITS+2:0] d_ram_read_index=d_speculative_read ? next_d_segment :
        {writeback_index,(d_state==D_WRITE_BEATS ? next_write_beat : d_beat)};
    wire d_ram_store=(d_state==D_LOOKUP && d_hit && d_complete && d_write);
    wire d_ram_fill=data_rd_rvalid_i &&
        ((d_state==D_READ_COMMAND && data_rd_gnt_i) || d_state==D_FILL);
    wire d_ram_write=!reset && (d_ram_store || d_ram_fill);
    wire d_ram_write_way=d_ram_store ? selected_way : request_way;
    wire [D_INDEX_BITS+2:0] d_ram_write_index=d_ram_store ? d_segment_index :
        {d_index,(d_state==D_READ_COMMAND ? 3'b0 : d_beat)};
    wire [63:0] d_ram_write_data=d_ram_store ? store_replicated : data_rd_rdata_i;
    wire [7:0] d_ram_write_mask=d_ram_store ? store_byte_enable : 8'hff;
    always @(posedge clk) begin
        if(i_ram_write) begin
            instruction_even[i_ram_write_index]<=instr_rdata_i[31:0];
            instruction_odd[i_ram_write_index]<=instr_rdata_i[63:32];
        end

    end

    wire [7:0] first_ram_write_mask=(d_ram_write && !d_ram_write_way) ? d_ram_write_mask : 8'b0;
    wire [7:0] second_ram_write_mask=(d_ram_write && d_ram_write_way) ? d_ram_write_mask : 8'b0;
    integer first_byte_lane,second_byte_lane;
    always @(posedge clk) begin
        for(first_byte_lane=0;first_byte_lane<8;first_byte_lane=first_byte_lane+1)
            if(first_ram_write_mask[first_byte_lane])
                data_segments[d_ram_write_index][first_byte_lane*8+:8]<=d_ram_write_data[first_byte_lane*8+:8];
        if(d_first_ram_read) d_first_ram_q<=data_segments[d_ram_read_index];
    end
    always @(posedge clk) begin
        for(second_byte_lane=0;second_byte_lane<8;second_byte_lane=second_byte_lane+1)
            if(second_ram_write_mask[second_byte_lane])
                data_segments_second[d_ram_write_index][second_byte_lane*8+:8]<=d_ram_write_data[second_byte_lane*8+:8];
        if(d_second_ram_read) d_second_ram_q<=data_segments_second[d_ram_read_index];
    end

    always @(posedge clk) begin
        if (reset) begin
            i_state<=I_IDLE; i_address<=0; begin i_even_bypass<=0; i_even_ram_select<=1'b0; end begin i_odd_bypass<=0; i_odd_ram_select<=1'b0; end i_tag<=0; i_valid<=0;
            i_crossing<=0; i_first_word<=0; i_first_error<=0;
            i_next_tag<=0; i_next_valid<=0;
            i_beat<=0; i_fill_error<=0; begin i_error_data_snapshot<=0;i_error_word_valid<=0;end i_error_bits<=0;
            d_state<=D_IDLE; d_address<=0; d_write<=0; d_wdata<=0;
            d_wstrb<=0; d_size<=0; begin d_first_bypass<=0; d_first_ram_select<=1'b0; end d_tag<=0; d_valid<=0;
            begin d_second_bypass<=0; d_second_ram_select<=1'b0; end d_second_tag<=0; d_second_valid<=0; d_second_dirty<=0; d_lru<=0;
            request_way<=0; writeback_way<=0; sweep_way<=0;
            d_dirty<=0; d_beat<=0; d_fill_error<=0; d_result<=0;
            d_result_error<=0; writeback_address<=0;
            writeback_index<=0; writeback_is_sweep<=0; sweep_index<=0;
            fence_pending<=0; invalidate_data<=0;
            for (n=0;n<I_LINES;n=n+1) instruction_valid[n]<=1'b0;
            for (n=0;n<D_LINES;n=n+1) begin
                data_valid[n]<=1'b0;
                data_dirty[n]<=1'b0;
                data_valid_second[n]<=1'b0;
                data_dirty_second[n]<=1'b0;
                data_lru[n]<=1'b0;
            end
        end else begin
            if (fence_i || fence_d) fence_pending<=1'b1;
            if (fence_d) invalidate_data<=1'b1;
            case (i_state)
                I_LOOKUP: begin
                    if (!i_hit) begin
                        i_beat<=0; i_fill_error<=0; i_state<=I_COMMAND;
                        instruction_valid[i_index]<=0;
                    end else if (!i_crossing && i_address[5:2]==4'd15 && !i_fast_cross_hit) begin
                        i_first_word<=i_word0;
                        i_first_error<=0;
                        i_crossing<=1;
                        i_address<=i_next_address;
                        if (!executable(i_next_address)) begin
                            begin i_error_data_snapshot<={32'b0,i_word0};i_error_word_valid<=1;end
                            i_error_bits<=2'b10; i_state<=I_ERROR;
                        end else begin
                            i_even_ram_select<=1'b1;
                            i_odd_ram_select<=1'b1;
                            i_tag<=instruction_tags[i_next_index];
                            i_valid<=instruction_valid[i_next_index];
                        end
                    end else if (i_complete) i_state<=I_IDLE;
                end
                I_COMMAND: if (instr_gnt_i) begin
                    i_state<=I_FILL;
                    i_beat<=0; i_fill_error<=0;
                    if (instr_rvalid_i) begin
                        // RAM write is in the common bank-port process below.
                        // RAM write is in the common bank-port process below.
                        if(i_address[5:3]==0)begin
                            begin i_odd_bypass<=instr_rdata_i[63:32]; i_odd_ram_select<=1'b0; end
                            if(!i_address[2])begin i_even_bypass<=instr_rdata_i[31:0]; i_even_ram_select<=1'b0; end
                        end
                        i_beat<=1; i_fill_error<=instr_err_i;
                    end
                end
                I_FILL: if (instr_rvalid_i) begin
                    // RAM write is in the common bank-port process below.
                    // RAM write is in the common bank-port process below.
                    if(i_beat==i_address[5:3])begin
                        begin i_odd_bypass<=instr_rdata_i[63:32]; i_odd_ram_select<=1'b0; end
                        if(!i_address[2])begin i_even_bypass<=instr_rdata_i[31:0]; i_even_ram_select<=1'b0; end
                    end
                    if(i_address[2] && i_address[5:3]!=3'd7 && i_beat==(i_address[5:3]+3'd1))
                        begin i_even_bypass<=instr_rdata_i[31:0]; i_even_ram_select<=1'b0; end
                    i_fill_error<=i_fill_error || instr_err_i;
                    if (i_beat==3'd7) begin
                        if (i_fill_error || instr_err_i) begin
                            if (!i_crossing && i_address[5:2]==4'd15 && executable(i_next_address)) begin
                                i_first_word<=0; i_first_error<=1; i_crossing<=1;
                                i_address<=i_next_address;
                                i_even_ram_select<=1'b1;
                                i_odd_ram_select<=1'b1;
                                i_tag<=instruction_tags[i_next_index];
                                i_valid<=instruction_valid[i_next_index];
                                i_state<=I_LOOKUP;
                            end else begin
                                begin i_error_data_snapshot<=i_crossing ? {32'b0,i_first_word} : 64'b0;i_error_word_valid<=i_crossing;end
                                i_error_bits<=i_crossing ? {1'b1,i_first_error} : 2'b11;
                                i_state<=I_ERROR;
                            end
                        end else begin
                            instruction_tags[i_index]<=i_address[31:6+I_INDEX_BITS];
                            instruction_valid[i_index]<=1'b1;
                            i_tag<=i_address[31:6+I_INDEX_BITS]; i_valid<=1;
                            i_state<=I_LOOKUP;
                        end
                    end else i_beat<=i_beat+3'd1;
                end
                I_ERROR: if (i_complete) i_state<=I_IDLE;
                default: begin end
            endcase
            // Acceptance has priority over completing the previous response.
            // A hit can therefore accept the next request on the same edge.
            if (new_i) begin
                i_address<=imem_request_address;
                i_crossing<=0; i_first_error<=0;
                if (!executable(imem_request_address) || imem_request_address[1:0]!=0) begin
                    i_state<=I_ERROR; i_error_bits<=2'b11; begin i_error_data_snapshot<=0;i_error_word_valid<=0;end
                end else begin
                    i_state<=I_LOOKUP;
                end
            end

            if(i_speculative_read)begin
                // Snapshot both tags at exactly the payload-read edge. No
                // maintenance can complete while an instruction is owned.
                // A refill of word0 cannot modify the distinct word1 index.
                if(ENABLE_FAST_ICROSS)begin
                    i_next_tag<=instruction_tags[new_i_next_index];
                    i_next_valid<=instruction_valid[new_i_next_index];
                end
                i_even_ram_select<=1'b1;i_odd_ram_select<=1'b1;
                i_tag<=instruction_tags[imem_request_address[6+I_INDEX_BITS-1:6]];
                i_valid<=instruction_valid[imem_request_address[6+I_INDEX_BITS-1:6]];
            end
            case (d_state)
                D_IDLE: if (fence_pending && i_state==I_IDLE) begin
                    sweep_index<=0; sweep_way<=0; d_state<=D_SWEEP_READ;
                end
                D_LOOKUP: begin
                    if (d_hit) begin
                        if (d_complete) begin
                            if (d_write) begin
                                if(selected_way)begin
                                    // Store byte enables use the common RAM write port.
                                    data_dirty_second[d_index]<=1'b1;
                                end else begin
                                    // Store byte enables use the common RAM write port.
                                    data_dirty[d_index]<=1'b1;
                                end
                            end
                            data_lru[d_index]<=!selected_way;
                            d_state<=D_IDLE;
                        end
                    end else if (selected_valid && selected_dirty) begin
                        request_way<=selected_way;
                        writeback_way<=selected_way;
                        writeback_address<={selected_tag,d_index,6'b0};
                        writeback_index<=d_index;
                        writeback_is_sweep<=0;
                        d_beat<=0; d_state<=D_WRITE_READ;
                    end else begin
                        request_way<=selected_way;
                        d_beat<=0; d_fill_error<=0; d_state<=D_READ_COMMAND;
                    end
                end
                D_READ_COMMAND: if (data_rd_gnt_i) begin
                    d_state<=D_FILL; d_beat<=0; d_fill_error<=0;
                    if(request_way)data_valid_second[d_index]<=0;
                    else data_valid[d_index]<=0;
                    if (data_rd_rvalid_i) begin
                        if(request_way)begin
                            // Refill uses the common RAM write port.
                            if(d_address[5:3]==0)begin d_second_bypass<=data_rd_rdata_i; d_second_ram_select<=1'b0; end
                        end else begin
                            // Refill uses the common RAM write port.
                            if(d_address[5:3]==0)begin d_first_bypass<=data_rd_rdata_i; d_first_ram_select<=1'b0; end
                        end
                        d_beat<=1;
                        d_fill_error<=data_rd_err_i || data_rd_rid_i!=1'b0;
                    end
                end
                D_FILL: if (data_rd_rvalid_i) begin
                    if(request_way)begin
                        // Refill uses the common RAM write port.
                        if(d_beat==d_address[5:3])begin d_second_bypass<=data_rd_rdata_i; d_second_ram_select<=1'b0; end
                    end else begin
                        // Refill uses the common RAM write port.
                        if(d_beat==d_address[5:3])begin d_first_bypass<=data_rd_rdata_i; d_first_ram_select<=1'b0; end
                    end
                    d_fill_error<=d_fill_error || data_rd_err_i || data_rd_rid_i!=1'b0;
                    if (d_beat==3'd7) begin
                        if (d_fill_error || data_rd_err_i || data_rd_rid_i!=1'b0) begin
                            d_result<=0; d_result_error<=1; d_state<=D_RESPONSE;
                        end else begin
                            if(request_way)begin
                                data_tags_second[d_index]<=d_address[31:6+D_INDEX_BITS];
                                data_valid_second[d_index]<=1; data_dirty_second[d_index]<=0;
                                d_second_tag<=d_address[31:6+D_INDEX_BITS]; d_second_valid<=1; d_second_dirty<=0;
                            end else begin
                                data_tags[d_index]<=d_address[31:6+D_INDEX_BITS];
                                data_valid[d_index]<=1; data_dirty[d_index]<=0;
                                d_tag<=d_address[31:6+D_INDEX_BITS]; d_valid<=1; d_dirty<=0;
                            end
                            d_state<=D_LOOKUP;
                        end
                    end else d_beat<=d_beat+3'd1;
                end
                D_WRITE_READ: begin
                    if(writeback_way)d_second_ram_select<=1'b1;
                    else d_first_ram_select<=1'b1;
                    d_state<=D_WRITE_BEATS;
                end
                D_WRITE_BEATS: if (data_wr_gnt_i) begin
                    if (d_beat==3'd7) begin
                        d_state<=D_WRITE_ACK;
                        // Accept a zero-latency completion on the final beat.
                        if (data_wr_bvalid_i && data_wr_bid_i==1'b0) begin
                            if (data_wr_berr_i) begin d_beat<=0; d_state<=D_WRITE_READ; end
                            else begin
                                if(writeback_way)data_dirty_second[writeback_index]<=0;
                                else data_dirty[writeback_index]<=0;
                                if (writeback_is_sweep) begin
                                    if (invalidate_data)begin
                                        if(writeback_way)data_valid_second[writeback_index]<=0;
                                        else data_valid[writeback_index]<=0;
                                    end
                                    if (sweep_is_last) begin
                                        for(n=0;n<I_LINES;n=n+1) instruction_valid[n]<=0;
                                        fence_pending<=fence_i || fence_d;
                                        invalidate_data<=fence_d;
                                        d_state<=D_IDLE;
                                    end else begin
                                        if(D_WAYS>1 && !sweep_way)sweep_way<=1;
                                        else begin sweep_way<=0; sweep_index<=sweep_index+1'b1; end
                                        d_state<=D_SWEEP_READ;
                                    end
                                end else begin d_beat<=0; d_state<=D_READ_COMMAND; end
                            end
                        end
                    end else begin
                        d_beat<=next_write_beat;
                        if(writeback_way)d_second_ram_select<=1'b1;
                        else d_first_ram_select<=1'b1;
                    end
                end
                D_WRITE_ACK: if (data_wr_bvalid_i && data_wr_bid_i==1'b0) begin
                    if (data_wr_berr_i) begin d_beat<=0; d_state<=D_WRITE_READ; end
                    else begin
                        if(writeback_way)data_dirty_second[writeback_index]<=0;
                        else data_dirty[writeback_index]<=0;
                        if (writeback_is_sweep) begin
                            if (invalidate_data)begin
                                if(writeback_way)data_valid_second[writeback_index]<=0;
                                else data_valid[writeback_index]<=0;
                            end
                            if (sweep_is_last) begin
                                for(n=0;n<I_LINES;n=n+1) instruction_valid[n]<=0;
                                fence_pending<=fence_i || fence_d;
                                invalidate_data<=fence_d;
                                d_state<=D_IDLE;
                            end else begin
                                if(D_WAYS>1 && !sweep_way)sweep_way<=1;
                                else begin sweep_way<=0; sweep_index<=sweep_index+1'b1; end
                                d_state<=D_SWEEP_READ;
                            end
                        end else begin d_beat<=0; d_state<=D_READ_COMMAND; end
                    end
                end
                D_IO_COMMAND: if (periph_gnt_i) begin
                    d_state<=D_IO_WAIT;
                    if (periph_rvalid_i) begin
                        d_result<=periph_rdata_i; d_result_error<=periph_err_i; d_state<=D_RESPONSE;
                    end
                end
                D_IO_WAIT: if (periph_rvalid_i) begin
                    d_result<=periph_rdata_i; d_result_error<=periph_err_i; d_state<=D_RESPONSE;
                end
                D_RESPONSE: if (d_complete) d_state<=D_IDLE;
                D_SWEEP_READ: begin
                    if(sweep_way)begin
                        d_tag<=data_tags_second[sweep_index];
                        d_valid<=data_valid_second[sweep_index]; d_dirty<=data_dirty_second[sweep_index];
                    end else begin
                        d_tag<=data_tags[sweep_index];
                        d_valid<=data_valid[sweep_index]; d_dirty<=data_dirty[sweep_index];
                    end
                    d_state<=D_SWEEP_CHECK;
                end
                D_SWEEP_CHECK: begin
                    if (d_valid && d_dirty) begin
                        writeback_address<={d_tag,sweep_index,6'b0};
                        writeback_way<=sweep_way;
                        writeback_index<=sweep_index; writeback_is_sweep<=1;
                        d_beat<=0; d_state<=D_WRITE_READ;
                    end else begin
                        if (invalidate_data)begin
                            if(sweep_way)data_valid_second[sweep_index]<=0;
                            else data_valid[sweep_index]<=0;
                        end
                        if (sweep_is_last) begin
                            for(n=0;n<I_LINES;n=n+1) instruction_valid[n]<=0;
                            fence_pending<=fence_i || fence_d;
                            invalidate_data<=fence_d;
                            d_state<=D_IDLE;
                        end else begin
                            if(D_WAYS>1 && !sweep_way)sweep_way<=1;
                            else begin sweep_way<=0; sweep_index<=sweep_index+1'b1; end
                            d_state<=D_SWEEP_READ;
                        end
                    end
                end
                default: begin end
            endcase
            // A held response has ready=0, so speculative data/tag reads
            // cannot replace its payload. Keep the original same-edge store
            // write forwarding and LRU/dirty bypass over these private reads.
            if(d_speculative_read)begin
                    d_first_ram_select<=1'b1; d_tag<=data_tags[next_d_index];
                    d_valid<=data_valid[next_d_index]; d_dirty<=data_dirty[next_d_index];
                    d_lru<=data_lru[next_d_index];
                    if(D_WAYS>1)begin
                        d_second_ram_select<=1'b1;
                        d_second_tag<=data_tags_second[next_d_index];
                        d_second_valid<=data_valid_second[next_d_index];
                        d_second_dirty<=data_dirty_second[next_d_index];
                    end else begin d_second_valid<=0; d_second_dirty<=0; end
                    if(d_complete && d_state==D_LOOKUP && next_d_index==d_index)
                        d_lru<=!selected_way;
                    // Explicit write-to-read forwarding avoids dependence on
                    // vendor-specific read-during-write memory behavior.
                    if (d_complete && d_state==D_LOOKUP && d_write && next_d_index==d_index) begin
                        if(selected_way)begin
                            d_second_dirty<=1;
                            if(next_d_segment==d_segment_index)begin d_second_bypass<=updated_data_segment; d_second_ram_select<=1'b0; end
                        end else begin
                            d_dirty<=1;
                            if(next_d_segment==d_segment_index)begin d_first_bypass<=updated_data_segment; d_first_ram_select<=1'b0; end
                        end
                    end
            end
            if(d_payload_free)begin
                d_address<=dmem_request_address; d_write<=dmem_request_write;
                d_wdata<=dmem_request_wdata; d_wstrb<=dmem_request_wstrb; d_size<=dmem_request_size;
            end
            if (new_d) begin
                // Preserve MMIO precedence and all original IO handshakes.
                // Only an accepted request owns this registered fault; held
                // responses, killed-load identity and alignment remain under
                // the unchanged cache/core transaction and exception rules.
                if (peripheral(dmem_request_address)) d_state<=D_IO_COMMAND;
                else if (!data_ram_mapped(dmem_request_address)) begin
                    d_result<=0; d_result_error<=1; d_state<=D_RESPONSE;
                end else begin
                    d_state<=D_LOOKUP;

                end
            end
        end
    end
endmodule
